<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulated payment receipt</title><link rel="stylesheet" href="<?= base_url('css/checkout.css') ?>"></head><body><main><p class="notice"><strong>TEST MODE / SIMULATED PAYMENT RECEIPT</strong></p><h1>Payment receipt</h1><dl><dt>Transaction reference</dt><dd><?= esc($payment['transaction_reference']) ?></dd><dt>Gateway transaction</dt><dd><?= esc($payment['gateway_transaction_id']) ?></dd><dt>Reservation reference</dt><dd><?= esc($payment['reservation_reference']) ?></dd><dt>Student</dt><dd><?= esc($payment['student_name']) ?> (<?= esc($payment['student_id']) ?>)</dd><dt>Method</dt><dd><?= esc(ucwords(str_replace('_', ' ', $payment['payment_method'])) ) ?></dd><dt>Amount</dt><dd><?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></dd><dt>Status</dt><dd><?= esc(ucfirst($payment['payment_status'])) ?></dd><dt>Created</dt><dd><?= esc($payment['created_at']) ?> UTC</dd><dt>Paid</dt><dd><?= esc($payment['paid_at'] ?? 'Not paid') ?></dd></dl><h2>Resources</h2><ul><?php foreach ($payment['rented_items_list'] as $item): ?><li><?= esc($item['name']) ?> — <?= (int) $item['quantity'] ?> <?= esc($item['type']) ?></li><?php endforeach ?></ul><p><button onclick="window.print()">Print receipt</button></p></main></body></html>
